// Package secrets supplies the credentials the original backend hard-coded in
// its C# source (JWT signing secret, Meta app secret, shared server API keys,
// TURN/RTC secrets, database password). Solara keeps the same values - they
// are shared with deployed clients, the game-server DLL and existing data -
// but never embeds them in Go source.
//
// Lookup order for NAME: environment variable SOLARA_<NAME>, then
// config/legacy-secrets.env (KEY=VALUE lines; generated by
// tools/scripts/extract-legacy-secrets.sh), searched next to the executable
// and in the working directory.
package secrets

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

// Names lists every secret the original source baked in.
var Names = []string{
	"JWT_SECRET", "META_APP_SECRET", "AUTOMATION_KEY", "SERVER_API_KEY", "ServerMasterKey",
	"QUEST_APP_SECRET", "TURN_SECRET", "RTC_API_KEY", "RTC_API_SECRET", "PRODUCTION_DB_PASSWORD",
}

var (
	once   sync.Once
	values = map[string]string{}
	// FilePath overrides the secrets file location (set before first Get).
	FilePath = ""
)

func load() {
	var candidates []string
	if FilePath != "" {
		candidates = []string{FilePath}
	} else {
		if exe, err := os.Executable(); err == nil {
			candidates = append(candidates, filepath.Join(filepath.Dir(exe), "config", "legacy-secrets.env"))
		}
		candidates = append(candidates, filepath.Join("config", "legacy-secrets.env"))
	}
	for _, p := range candidates {
		f, err := os.Open(p)
		if err != nil {
			continue
		}
		sc := bufio.NewScanner(f)
		for sc.Scan() {
			line := strings.TrimSpace(sc.Text())
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			if k, v, ok := strings.Cut(line, "="); ok {
				values[strings.TrimSpace(k)] = v
			}
		}
		_ = f.Close()
		return
	}
}

// Get returns the secret NAME ("" when unconfigured).
func Get(name string) string {
	once.Do(load)
	if v, ok := os.LookupEnv("SOLARA_" + name); ok {
		return v
	}
	return values[name]
}

// Missing reports which known secrets are not configured.
func Missing() []string {
	var out []string
	for _, n := range Names {
		if Get(n) == "" {
			out = append(out, n)
		}
	}
	return out
}

// Set overrides a value (tests).
func Set(name, value string) {
	once.Do(load)
	values[name] = value
}
